package thumbs

import "testing"

func TestLRUPromotesAndEvicts(t *testing.T) {
	c := NewLRU(2)
	c.Put("alder", []byte("A"))
	c.Put("birch", []byte("B"))
	c.Get("alder")
	c.Put("cedar", []byte("C"))
	if got, ok := c.Get("alder"); !ok || string(got) != "A" {
		t.Fatalf("Get(alder) = %q, %v; want A, true", got, ok)
	}
	if _, ok := c.Get("birch"); ok {
		t.Fatal("birch should have been evicted")
	}
	if got, ok := c.Get("cedar"); !ok || string(got) != "C" {
		t.Fatalf("Get(cedar) = %q, %v; want C, true", got, ok)
	}
}

func TestLRURespectsByteLimit(t *testing.T) {
	c := NewLRU(3)
	c.Put("oak", []byte("123"))
	c.Put("pine", []byte("456"))
	if c.Len() != 1 {
		t.Fatalf("Len() = %d; want 1", c.Len())
	}
	if got, ok := c.Get("pine"); !ok || string(got) != "456" {
		t.Fatalf("Get(pine) = %q, %v; want 456, true", got, ok)
	}
	if _, ok := c.Get("oak"); ok {
		t.Fatal("oak should have been evicted")
	}
}
