export interface Reading {
  site: string;
  pCiL: number;
}

export function weeklySummary(readings: Reading[]) {
  const summary: Record<string, { normal: number; outOfRange: number }> = {};
  for (const reading of readings) {
    summary[reading.site] ??= { normal: 0, outOfRange: 0 };
    if (reading.pCiL < 4) summary[reading.site].normal++;
    else summary[reading.site].outOfRange++;
  }
  return summary;
}
