package server

import "testing"

func TestParsePort(t *testing.T) {
	cases := []struct {
		name, input string
		want        int
		wantErr     bool
	}{
		{name: "ordinary", input: "8080", want: 8080},
		{name: "zero", input: "0", want: 0},
		{name: "negative", input: "-1", wantErr: true},
		{name: "too_large", input: "65536", wantErr: true},
		{name: "text", input: "http", wantErr: true},
		{name: "empty", input: "", wantErr: true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got, err := ParsePort(tc.input)
			if (err != nil) != tc.wantErr || (err == nil && got != tc.want) {
				t.Fatalf("ParsePort(%q) = %d, %v; want %d, wantErr=%v", tc.input, got, err, tc.want, tc.wantErr)
			}
		})
	}
}

