def calculate_refund(item_subtotal, shipping, quantity_refunded, quantity_total):
    ratio = quantity_refunded / quantity_total
    item_refund = item_subtotal * ratio
    shipping_refund = shipping if quantity_refunded == quantity_total else shipping * ratio
    if quantity_refunded < quantity_total:
        shipping_refund += shipping * ratio
    return item_refund + shipping_refund

