export type CartState = { items: Record<string, number>; total: number };
export type Action =
  | { type: 'cart/add'; sku: string; quantity: number }
  | { type: 'cart/remove'; sku: string }
  | { type: 'cart/clear' };
export const initialState: CartState = { items: {}, total: 0 };

export function reducer(state: CartState = initialState, action: Action): CartState {
  if (action.type === 'cart/add') {
    const quantity = state.items[action.sku] ?? 0;
    return { items: { ...state.items, [action.sku]: quantity + action.quantity }, total: state.total + action.quantity };
  } else if (action.type === 'cart/remove') {
    const quantity = state.items[action.sku] ?? 0;
    if (!quantity) return state;
    const items = { ...state.items };
    delete items[action.sku];
    return { items, total: state.total - quantity };
  } else if (action.type === 'cart/clear') {
    return initialState;
  }
  return state;
}
