#include "opcodes.h"

static const Opcode opcodes[] = {
    {0x01, "NOP"},
    {0x10, "LDA"},
    {0x20, "JMP"}
};

const char *opcode_name(unsigned code) {
    size_t lo = 0, hi = sizeof opcodes / sizeof opcodes[0];
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (opcodes[mid].code < code) lo = mid + 1;
        else hi = mid;
    }
    if (lo < (sizeof opcodes / sizeof opcodes[0]) - 1 &&
        opcodes[lo].code == code) return opcodes[lo].name;
    return NULL;
}
