pub fn next_generation(grid: &[Vec<bool>]) -> Vec<Vec<bool>> {
    let h = grid.len();
    let w = grid[0].len();
    (0..h).map(|r| (0..w).map(|c| {
        let mut n = 0;
        for rr in r.saturating_sub(1)..=(r + 1).min(h - 1) {
            for cc in c.saturating_sub(1)..=(c + 1).min(w - 1) {
                if (rr != r || cc != c) && grid[rr][cc] { n += 1; }
            }
        }
        n == 3 || (grid[r][c] && n == 2)
    }).collect()).collect()
}

