use std::env;

#[derive(Debug, PartialEq)]
struct Options {
    input: String,
    output: String,
    width: u32,
    height: Option<u32>,
}

fn parse_args(args: &[String]) -> Result<Options, String> {
    let (mut input, mut output, mut width, mut height) = (None, None, None, None);
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--input" => { input = Some(args[i + 1].clone()); i += 2; }
            "--output" => { output = Some(args[i + 1].clone()); i += 2; }
            "--width" => { width = Some(args[i + 1].parse().map_err(|_| "invalid --width")?); i += 2; }
            _ => return Err(format!("unknown flag {}", args[i])),
        }
    }
    Ok(Options {
        input: input.ok_or("missing --input")?,
        output: output.ok_or("missing --output")?,
        width: width.ok_or("missing --width")?,
        height,
    })
}

fn main() {
    let args: Vec<String> = env::args().skip(1).collect();
    match parse_args(&args) {
        Ok(opts) => println!("{:?}", opts),
        Err(err) => eprintln!("{err}"),
    }
}

