package cron

import (
	"errors"
	"strconv"
	"strings"
	"time"
)

func field(s string, max int) (map[int]bool, error) {
	out := map[int]bool{}
	for _, part := range strings.Split(s, ",") {
		lo, hi := 0, 0
		if part == "*" {
			hi = max
		} else if pair := strings.Split(part, "-"); len(pair) == 2 {
			var err error
			lo, err = strconv.Atoi(pair[0])
			if err != nil { return nil, errors.New("invalid field") }
			hi, err = strconv.Atoi(pair[1])
			if err != nil { return nil, errors.New("invalid field") }
		} else {
			var err error
			lo, err = strconv.Atoi(part)
			if err != nil { return nil, errors.New("invalid field") }
			hi = lo
		}
		if lo < 0 || hi > max || lo > hi { return nil, errors.New("field out of range") }
		for n := lo; n <= hi; n++ { out[n] = true }
	}
	return out, nil
}

func Next(expr string, after time.Time) (time.Time, error) {
	f := strings.Fields(expr)
	if len(f) != 2 { return time.Time{}, errors.New("expected minute and hour fields") }
	mins, err := field(f[0], 59)
	if err != nil { return time.Time{}, err }
	hours, err := field(f[1], 23)
	if err != nil { return time.Time{}, err }
	for t, end := after.Truncate(time.Minute).Add(time.Minute), after.AddDate(1, 0, 0); t.Before(end); t = t.Add(time.Minute) {
		if mins[t.Minute()] && hours[t.Hour()] { return t, nil }
	}
	return time.Time{}, errors.New("no occurrence within one year")
}
EOF
