pub fn mix(a: &[i16], b: &[i16]) -> Vec<i16> {
    (0..a.len().max(b.len()))
        .map(|i| {
            let left = i32::from(*a.get(i).unwrap_or(&0));
            let right = i32::from(*b.get(i).unwrap_or(&0));
            (left + right).clamp(i32::from(i16::MIN), i32::from(i16::MAX)) as i16
        })
        .collect()

