import json

class RateLimiter:
    def __init__(self, limit, window):
        self.limit = limit
        self.window = window
        self.timestamps = []

    def allow(self, now):
        self.timestamps = [t for t in self.timestamps if now - t <= self.window]
        if len(self.timestamps) <= self.limit:
            self.timestamps.append(now)
            return True
        return False

def main():
    limiter = RateLimiter(limit=2, window=10)
    accepted = sum(limiter.allow(t) for t in (0, 1, 2))
    result = {
        "accepted": accepted,
        "limit": limiter.limit,
        "score": 100 if accepted == limiter.limit else 0,
        "ok": accepted == limiter.limit,
    }
    Path("results.json").write_text(json.dumps(result) + "\n")
    print(json.dumps(result))

if __name__ == "__main__":
    main()
